    Map<String, Integer> lastPrintedTime = new HashMap<>();

    // Check if the message has been printed within the last 10 seconds
    if (lastPrintedTime.containsKey(message) && timestamp - lastPrintedTime.get(message) < 10) {
        return false;
    }

    // Update the last printed time for the message
    lastPrintedTime.put(message, timestamp);

    // Return true if the message should be printed
    return true;
}

