import org.jgrapht.graph.DefaultGraphPath;

public class GraphPathTransformer {

    /**
     * Transform from a Set representation to a graph path.
     * @param tour a set containing the edges of the tour
     * @param graph the graph
     * @return a graph path
     */
    protected GraphPath<V, DefaultEdge> edgeSetToTour(Set<E> tour, Graph<V, DefaultEdge> graph) {
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        GraphPath<V, DefaultEdge> path = new DefaultGraphPath<>();
        for (E edge : tour) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            path.addVertex(source);
            path.addVertex(target);
            path.addEdge(source, target);
        }

        return path;
    }
}

