import com.mongodb.client.model.Filters;
import com.mongodb.client.model.Updates;
import org.bson.Document;
import org.bson.types.ObjectId;

public class Meteor {
    private static MongoClient mongoClient;
    private static MongoDatabase database;
    private static MongoCollection<Document> collection;

    static {
        String uri = "mongodb://localhost:27017";
        MongoClientURI mongoClientURI = new MongoClientURI(uri);
        mongoClient = new MongoClient(mongoClientURI);
        database = mongoClient.getDatabase("meteorDB");
        collection = database.getCollection("meteorCollection");
    }

    public static Meteor lookup(HttpServletRequest r) {
        String userId = r.getHeader("userId");
        if (userId == null) {
            return null;
        }

        Document query = new Document("_id", new ObjectId(userId));
        try (MongoCursor<Document> cursor = collection.find(query).iterator()) {
            if (cursor.hasNext()) {
                return new Meteor(cursor.next());
            }
        } catch (MongoWriteException e) {
            e.printStackTrace();
        }
        return null;
    }
}

