        throw new IllegalArgumentException("Both str and substring must not be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Index must be within the bounds of the string");
    }
    if (substring.length() > str.length() - index) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

