import java.util.ArrayList;
import java.util.List;

public class AppenderManager {
    private List<Appender> appenders;

    public AppenderManager() {
        this.appenders = new ArrayList<>();
    }

    public void addAppender(Appender appender) {
        this.appenders.add(appender);
    }

    public void removeAppender(String name) {
        this.appenders.removeIf(appender -> appender.getName().equals(name));
    }

    public static void main(String[] args) {
        AppenderManager manager = new AppenderManager();
        manager.addAppender(new Appender("Appender1"));
        manager.addAppender(new Appender("Appender2"));
        manager.removeAppender("Appender1");
        System.out.println(manager.appenders); // Output: [Appender2]
    }
}

class Appender {
    private String name;

    public Appender(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

